    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which federal law protects the privacy and security of a patient''s identifiable health information?', '["EMTALA", "HIPAA", "ERISA", "COBRA"]', 1, 'The Health Insurance Portability and Accountability Act (HIPAA) of 1996 established the national standards for protecting sensitive patient health information.'),
    (v_topic_id, 'A physician discusses a patient''s case in a crowded hospital elevator, and the patient''s name is mentioned. This is a violation of:', '["Justice", "Autonomy", "Confidentiality", "Veracity"]', 2, 'Confidentiality requires that patient information be shared only in private, professional settings with those who have a need to know.'),
    (v_topic_id, 'Under HIPAA, "Protected Health Information" (PHI) includes which of the following?', '["Name and date of birth", "Social Security number", "Medical record number", "All of the above"]', 3, 'PHI includes any information that can be used to identify a patient and relates to their past, present, or future physical or mental health.'),
    (v_topic_id, 'A 17-year-old girl is treated for a sexually transmitted infection. Her parents call and ask for her test results. According to many state laws and HIPAA, the physician should:', '["Provide the results immediately", "Refuse to share the results without the minor''s explicit consent", "Tell the parents to ask the girl", "Call the police"]', 1, 'In many states, minors who can consent to their own STI care also have a right to confidentiality regarding that care, even from their parents.'),
    (v_topic_id, 'Which of the following is a situation where a physician is *required* to break confidentiality without the patient''s consent?', '["A patient confesses to a past theft", "A patient has a suspected case of child abuse", "A patient admits to cheating on their spouse", "A patient is famous and the media is asking questions"]', 1, 'Mandatory reporting laws require physicians to report suspected child abuse, elder abuse, and certain communicable diseases to the appropriate authorities.'),
    (v_topic_id, 'The "Tarasoff" case established the legal "Duty to Warn." This means a physician must break confidentiality if:', '["A patient is using illegal drugs", "A patient makes a credible threat of serious harm to a specific, identifiable third party", "A patient is not following their treatment plan", "A patient is diagnosed with a terminal illness"]', 1, 'The Duty to Warn (or Duty to Protect) applies when there is a clear danger to an identifiable individual.'),
    (v_topic_id, 'A physician is notified that a patient has been diagnosed with a reportable disease (e.g., Syphilis). The physician must:', '["Tell the patient''s employer", "Notify the local or state health department", "Notify the patient''s neighbors", "Keep it a secret to protect the patient''s privacy"]', 1, 'Public health reporting of certain infectious diseases is a legal requirement that overrides individual confidentiality for the sake of community safety.'),
    (v_topic_id, 'A police officer asks a physician for the blood alcohol level of a conscious, competent patient who was involved in a car accident. The patient refuses to consent. The physician should:', '["Provide the information anyway", "Refuse to share the information without a warrant or the patient''s consent (unless specific state law mandates it)", "Tell the officer to ask the nurse", "Give the officer a fake number"]', 1, 'Physicians should protect patient privacy unless there is a legal mandate (like a warrant) or the patient consents.'),
    (v_topic_id, 'Does HIPAA allow a physician to share PHI with another healthcare provider for the purpose of treating the patient?', '["No, not without a signed release for every single interaction", "Yes, HIPAA allows for the sharing of information for Treatment, Payment, and Healthcare Operations (TPO) without specific patient authorization", "Only if the providers are in the same building", "Only if the patient is a minor"]', 1, 'The TPO exception is essential for the coordination of care between different members of the healthcare team.'),
    (v_topic_id, 'A patient''s employer calls to ask why the patient was in the hospital. The physician should:', '["Tell the truth so the patient doesn''t lose their job", "Refuse to provide any information without the patient''s written authorization", "Tell the employer to check the patient''s Facebook", "Lie and say the patient wasn''t there"]', 1, 'Employment status does not grant access to private medical information without the patient''s explicit permission.'),
    (v_topic_id, 'A 70-year-old man presents with suspicious bruises in various stages of healing and appears fearful of his caregiver. The physician should:', '["Ask the caregiver what happened", "Report the case to Adult Protective Services (APS) or the appropriate elder abuse agency", "Tell the man to move out", "Wait for more evidence"]', 1, 'Physicians are mandatory reporters for suspected elder abuse or neglect.'),
    (v_topic_id, 'Which of the following is true about reporting domestic violence (Intimate Partner Violence) involving competent adults?', '["It is mandatory in all 50 states", "It is generally not mandatory to report to the police without the victim''s consent, unless there is a specific injury (like a gunshot wound) that triggers a different reporting law", "The physician should call the victim''s parents", "The physician should confront the abuser"]', 1, 'For competent adults, reporting domestic violence to the police against the victim''s will can sometimes increase the danger to the victim. The focus is on providing resources and safety planning.'),
    (v_topic_id, 'A physician sees a patient''s name on a sign-in sheet at a clinic. Is this a HIPAA violation?', '["Yes, always", "No, as long as the information is limited and used for legitimate clinic operations (though ''incidental disclosures'' should be minimized)", "Only if the patient is a celebrity", "Only if the sheet also lists the diagnosis"]', 1, 'Incidental disclosures are allowed if the clinic has implemented reasonable safeguards (like not listing the reason for the visit on the sign-in sheet).'),
    (v_topic_id, 'A patient dies. Does their HIPAA protection end?', '["Yes, immediately", "No, HIPAA protections generally continue for 50 years after the patient''s death", "Only if the family agrees", "Only if it was a famous person"]', 1, 'Privacy rights extend beyond death to protect the patient''s dignity and the privacy of their survivors.'),
    (v_topic_id, 'A physician wants to use a patient''s photograph in a medical journal. They should:', '["Use it as long as the eyes are covered", "Obtain specific, written authorization from the patient to use the image for publication", "Assume the patient would be honored", "Just use it, it''s for education"]', 1, 'Using identifiable images requires explicit permission from the patient.'),
    (v_topic_id, 'A patient is being treated for a gunshot wound. In most states, the physician:', '["Must keep it confidential", "Is legally required to report the injury to law enforcement", "Should wait for the patient to tell the police", "Should call the media"]', 1, 'Gunshot wounds and other "injuries by a deadly weapon" are typically mandatory reporting items to the police.'),
    (v_topic_id, 'A physician is subpoenaed to testify in a court case about a patient. What should they do first?', '["Provide all the records immediately", "Contact the patient (or their lawyer) to see if they waive their patient-physician privilege, and consult with their own legal counsel", "Ignore the subpoena", "Tell the patient to run away"]', 1, 'A subpoena is a legal demand, but patient-physician privilege may still apply. The physician must ensure that the release of information is legally authorized.'),
    (v_topic_id, 'Which of the following is NOT an exception to confidentiality?', '["Suspected child abuse", "A patient''s diagnosis of HIV (except for specific partner notification laws in some states)", "A patient''s threat to blow up a bridge", "An unconscious patient who needs a life-saving blood transfusion from a known family member"]', 1, 'While HIV is a reportable condition to health departments, the physician cannot generally disclose it to others without consent or a specific legal mandate.'),
    (v_topic_id, 'A patient with poorly controlled epilepsy continues to drive against medical advice. In some states, the physician:', '["Must call the police", "May be required or allowed to report the patient to the Department of Motor Vehicles (DMV)", "Should disable the patient''s car", "Must ignore it to protect confidentiality"]', 1, 'Public safety concerns regarding impaired driving can override confidentiality in some jurisdictions.'),
    (v_topic_id, 'What is the "Minimum Necessary" rule in HIPAA?', '["The physician should charge the minimum fee", "The physician should only disclose the minimum amount of PHI necessary to accomplish the intended purpose", "The physician should see the patient for the minimum amount of time", "None of the above"]', 1, 'The "minimum necessary" standard ensures that privacy is maintained by not over-sharing information.'),
    (v_topic_id, 'A physician leaves a message on a patient''s home answering machine. They should:', '["Leave the full details of the lab results", "Leave only their name, the clinic name, and a call-back number, avoiding sensitive medical information", "Identify themselves as the ''Urologist", "None of the above"]', 1, 'Messages should be kept brief and vague to protect privacy in case someone else hears them.'),
    (v_topic_id, 'A 15-year-old boy is found to be using marijuana by his pediatrician. The boy asks the doctor not to tell his parents. The doctor should:', '["Tell the parents immediately", "Encourage the boy to talk to his parents and explain the risks, but in many states, this information is confidential unless it poses an immediate life-threatening risk", "Call the school", "Call the police"]', 1, 'Drug use in minors is a sensitive area. Confidentiality is often maintained to encourage honest communication and treatment, unless the minor is at high risk of immediate harm (e.g., overdose or suicide).'),
    (v_topic_id, 'A patient wants to correct an error in their medical record. According to HIPAA, the physician:', '["Can refuse without reason", "Must allow the patient to request an amendment to their record", "Must delete the original note", "Can charge a fee to change it"]', 1, 'Patients have a right to request that inaccuracies in their PHI be amended.'),
    (v_topic_id, 'A "Covered Entity" under HIPAA includes:', '["A health insurance company", "A hospital", "A pharmacy", "All of the above"]', 3, 'Covered entities are any organizations that handle PHI in the course of healthcare or insurance.'),
    (v_topic_id, 'A "Business Associate" under HIPAA is:', '["A person who sells medical equipment", "A third party (like a billing company or IT consultant) that performs services for a covered entity and handles PHI", "The doctor''s spouse", "None of the above"]', 1, 'Business associates must sign a contract (Business Associate Agreement) promising to protect PHI.'),
    (v_topic_id, 'A physician is working on a research project and wants to use data from his own patients. He must:', '["Just use it, he owns the data", "Get IRB approval and potentially obtain specific consent from the patients (or a waiver of consent from the IRB)", "Tell the patients later", "Only use data from patients he likes"]', 1, 'Using patient data for research requires oversight and often explicit consent, even if the doctor is the one who collected it.'),
    (v_topic_id, 'A patient presents with a stage IV pressure ulcer and is severely malnourished. They are under the care of a family member. The physician should:', '["Advise the family to use more lotion", "Report suspected neglect to Adult Protective Services", "Assume it''s just part of aging", "None of the above"]', 1, 'Severe pressure ulcers in a dependent adult are a red flag for neglect.'),
    (v_topic_id, 'A teacher calls a pediatrician to ask why a student was absent from school. The pediatrician should:', '["Tell the teacher the truth", "Refuse to provide information without parental consent", "Say the child was ''just sick", "Tell the teacher to call the principal"]', 1, 'Even for minor issues, school absence notes should only contain the information authorized by the parent.'),
    (v_topic_id, 'Which of the following is a situation where PHI can be disclosed without authorization for "Public Interest and Benefit" activities?', '["Judicial and administrative proceedings", "Workers'' compensation claims", "Organ and tissue donation", "All of the above"]', 3, 'HIPAA allows for limited disclosures in these specific areas without individual authorization.'),
    (v_topic_id, 'A physician receives a "Notice of Privacy Practices" from their dentist. This document explains:', '["How much the dentist charges", "How the dentist''s office will use and disclose the patient''s health information and the patient''s rights under HIPAA", "The dentist''s vacation schedule", "None of the above"]', 1, 'Covered entities must provide this notice to all patients.'),
    (v_topic_id, 'A patient''s sister calls to ask how the patient is doing after a surgery. The patient is currently awake and competent. The physician should:', '["Tell the sister everything", "Ask the patient for permission before sharing any information with the sister", "Tell the sister it''s none of her business", "Ask the sister for her ID"]', 1, 'Respect for autonomy means the patient decides who gets to know about their medical status.'),
    (v_topic_id, 'A patient is unconscious. The physician shares update information with the patient''s spouse. This is:', '["A HIPAA violation", "Ethically and legally permissible under ''Professional Judgment'' when it is in the patient''s best interest and the patient has not previously objected", "Illegal without a written proxy", "Only allowed if the patient is a minor"]', 1, 'When the patient is incapacitated, physicians can share relevant information with family members or friends involved in the patient''s care.'),
    (v_topic_id, 'A physician uses a personal, unencrypted laptop to store patient records. The laptop is stolen. This is:', '["A minor mistake", "A significant HIPAA security breach that must be reported to the Department of Health and Human Services (HHS) and the affected patients", "Not a problem if the laptop had a password", "The patient''s fault"]', 1, 'PHI must be stored and transmitted using secure, encrypted methods.'),
    (v_topic_id, 'If a patient is diagnosed with Tuberculosis (TB), the physician must:', '["Tell the patient to move out of their house", "Notify the local public health department to facilitate contact tracing", "Tell the patient''s employer", "Keep it a secret"]', 1, 'TB is a highly reportable disease due to the public health risk.'),
    (v_topic_id, 'A "De-identified" dataset under HIPAA:', '["Still has the patient''s initials", "Has had all 18 specific identifiers removed (name, SSN, etc.) so that it can no longer be linked to an individual", "Is only for research", "None of the above"]', 1, 'Once de-identified, information is no longer PHI and is no longer subject to HIPAA.'),
    (v_topic_id, 'A physician is treating a patient for a bite from a neighbor''s dog. In most states, the physician must:', '["Report the bite to the local health department or animal control", "Report the neighbor to the police", "Call a lawyer", "Kill the dog"]', 0, 'Animal bites are reportable to track potential rabies exposure.'),
    (v_topic_id, 'A 16-year-old girl wants an abortion. In a state with "Parental Notification" laws, the physician must:', '["Tell the parents regardless of the minor''s wishes (unless a judicial bypass is obtained)", "Keep it confidential", "Call the court", "None of the above"]', 0, 'Parental notification/consent laws for abortion are common and legally distinct from other sensitive minor care.'),
    (v_topic_id, 'A physician sees a patient in a grocery store. The physician should:', '["Say ''Hello, how is your diabetes?", "Wait for the patient to initiate contact and avoid discussing medical issues in public", "Ignore the patient entirely", "Tell the cashier the patient has a great insurance plan"]', 1, 'Protecting the patient''s privacy in public settings is part of professional confidentiality.'),
    (v_topic_id, 'A patient requests a copy of their own mental health therapy notes. Under HIPAA, the physician:', '["Must provide them immediately", "Can refuse to provide psychotherapy notes if they are kept separate from the rest of the medical record", "Can only give them to the patient''s lawyer", "Can charge $1000 for them"]', 1, 'HIPAA has a specific exception for psychotherapy notes, which are considered more sensitive than general medical information.'),
    (v_topic_id, 'A physician notices a nurse is accessing the records of a celebrity who is not under the nurse''s care. This is:', '["A ''need to know'' violation and a HIPAA breach", "Curiosity, which is fine in a hospital", "Only a problem if the nurse tells someone", "None of the above"]', 0, 'Employees should only access the records of patients they are directly caring for.'),
    (v_topic_id, 'A patient is diagnosed with a genetic condition that has significant implications for their siblings. The patient refuses to tell them. The physician should:', '["Break confidentiality and call the siblings", "Respect the patient''s confidentiality but strongly encourage them to share the information or allow the physician to share it anonymously", "Wait for the siblings to get sick", "None of the above"]', 1, 'While some ethical guidelines allow for disclosure if the risk of harm is high and preventable, the legal standard generally favors patient confidentiality in genetic testing.'),
    (v_topic_id, 'The "Genetic Information Nondiscrimination Act" (GINA) prohibits:', '["Doctors from doing genetic tests", "Health insurers and employers from discriminating based on genetic information", "Patients from knowing their own results", "None of the above"]', 1, 'GINA provides protections for patients who undergo genetic testing.'),
    (v_topic_id, 'A physician is working on a patient who was a victim of a crime. The police ask for the patient''s clothes as evidence. The physician should:', '["Refuse", "Hand over the evidence while following the chain-of-custody protocols required by law", "Throw the clothes away", "Give them to the patient''s family"]', 1, 'Cooperation with law enforcement in criminal investigations is often legally required and follows specific procedures for evidence handling.'),
    (v_topic_id, 'If a patient has a positive test for a reportable STI, the health department may contact them for "Partner Notification." This is done to:', '["Embarrass the patient", "Identify and treat other individuals who may have been exposed to the infection", "Collect fines", "None of the above"]', 1, 'Partner notification is a key public health tool for controlling the spread of STIs.'),
    (v_topic_id, 'A patient is admitted to a hospital. Can the hospital include the patient''s name in the "Hospital Directory" (so callers can find their room)?', '["No, never", "Yes, unless the patient specifically opts out of being listed", "Only if the patient is a VIP", "Only for family members"]', 1, 'Hospitals typically allow directory listing unless the patient requests privacy.'),
    (v_topic_id, 'Which of the following is true about "Mandatory Reporting" of child abuse?', '["The physician must be 100% certain that abuse occurred before reporting", "The physician is legally required to report if they have a ''reasonable suspicion'' of abuse or neglect", "The physician should wait for the parents to confess", "Reporting is optional if the family seems ''nice"]', 1, 'The threshold for reporting is "reasonable suspicion." The investigation is the job of the authorities (CPS/police).'),
    (v_topic_id, 'A physician who reports child abuse in good faith is:', '["Likely to be sued for defamation", "Legally protected from civil and criminal liability for making the report", "Going to lose their license", "None of the above"]', 1, 'Immunity for good-faith reporting is a standard feature of mandatory reporting laws.'),
    (v_topic_id, 'Under HIPAA, can a physician use unencrypted email to communicate with a patient?', '["No, it is strictly forbidden", "Yes, but only if the patient is warned of the risks and still requests to use email", "Only for appointment reminders", "None of the above"]', 1, 'If the patient is aware of the security risks and chooses to use unencrypted email, the physician can comply.'),
    (v_topic_id, 'A physician is leaving their practice to move to a different state. They must:', '["Shred all their records", "Notify their patients and provide a way for them to access or transfer their records to a new provider", "Take all the original records with them", "None of the above"]', 1, 'Ensuring the security and availability of medical records is a continuing professional duty.'),
    (v_topic_id, 'A "Sentinel Event" in a hospital is defined by the Joint Commission as:', '["Any patient death", "An unexpected occurrence involving death or serious physical or psychological injury, or the risk thereof", "A successful surgery", "A high patient satisfaction score"]', 1, 'Sentinel events (like wrong-site surgery) require immediate investigation and a "Root Cause Analysis" (RCA).');
